// 1. Extract query parameters from webhook
const query = $json.query || $json;

// 2. Extract authenticated user identifiers
const authenticatedUserId = String(query.userId || query['user ID'] || query.id || '').trim();
const userEmail = String(query.userEmail || query.email || '').trim().toLowerCase();
const dateFilter = String(query.date || '').trim();
const getAction = String(query.Get || query.action || 'get_all_tasks').trim();

// 3. Validate user authentication context
if (!authenticatedUserId && !userEmail) {
  return {
    json: {
      isError: true,
      statusCode: 401,
      error: {
        message: 'المستخدم غير مصادق، يرجى تسجيل الدخول أولاً لعرض المهام',
        code: 'UNAUTHENTICATED_USER',
        field: 'userId'
      }
    }
  };
}

return {
  json: {
    isError: false,
    databaseId: '3dc6fd16-45b0-8072-9e75-fb87ba35ed28',
    usersDatabaseId: '3dc6fd16-45b0-80ff-8435-c255ed191886',
    userId: authenticatedUserId,
    'user ID': authenticatedUserId,
    userEmail: userEmail,
    date: dateFilter,
    Get: getAction
  }
};

// 1. Extract target user credentials from validation node
const userContext = $('Extract and Validate GET Request').first().json;
const targetUserId = String(userContext.userId || userContext['user ID'] || '').trim();
const targetEmail = String(userContext.userEmail || '').trim().toLowerCase();
const dateFilter = String(userContext.date || '').trim();

// 2. Collect all task items returned by Notion
const items = $input.all();
const parsedTasks = [];

for (let i = 0; i < items.length; i++) {
  const rawItem = items[i].json;
  if (!rawItem || rawItem.error) continue;

  const props = rawItem.properties || rawItem;

  // Extract Task User ID
  let taskUserId = '';
  if (props['user ID']?.rich_text?.[0]?.plain_text) {
    taskUserId = props['user ID'].rich_text[0].plain_text.trim();
  } else if (props['user ID']?.title?.[0]?.plain_text) {
    taskUserId = props['user ID'].title[0].plain_text.trim();
  } else if (typeof props['user ID'] === 'string') {
    taskUserId = props['user ID'].trim();
  } else if (rawItem['user ID']) {
    taskUserId = String(rawItem['user ID']).trim();
  }

  // Extract ID_task
  let idTask = '';
  if (props.ID_task?.rich_text?.[0]?.plain_text) {
    idTask = props.ID_task.rich_text[0].plain_text.trim();
  } else if (typeof props.ID_task === 'string') {
    idTask = props.ID_task.trim();
  } else {
    idTask = rawItem.id || `task-${i}-${Date.now()}`;
  }

  // Filter strictly for this authenticated user
  const isMatchingUser = targetUserId && taskUserId
    ? (taskUserId === targetUserId || taskUserId.includes(targetUserId) || targetUserId.includes(taskUserId))
    : true;

  if (!isMatchingUser) {
    continue;
  }

  // Extract Title
  let title = '';
  if (props['العنوان']?.title?.[0]?.plain_text) {
    title = props['العنوان'].title[0].plain_text;
  } else if (props.Title?.title?.[0]?.plain_text) {
    title = props.Title.title[0].plain_text;
  } else if (props.title?.title?.[0]?.plain_text) {
    title = props.title.title[0].plain_text;
  } else if (props.name) {
    title = props.name;
  }

  // Extract Description
  let description = '';
  if (props['الوصف']?.rich_text?.[0]?.plain_text) {
    description = props['الوصف'].rich_text[0].plain_text;
  } else if (props.Description?.rich_text?.[0]?.plain_text) {
    description = props.Description.rich_text[0].plain_text;
  } else if (props.description) {
    description = props.description;
  }

  // Extract Status
  let status = 'قيد الانتظار';
  if (props['الحالة']?.select?.name) {
    status = props['الحالة'].select.name;
  } else if (props['الحالة']?.status?.name) {
    status = props['الحالة'].status.name;
  } else if (props.Status?.status?.name) {
    status = props.Status.status.name;
  } else if (props.Status?.select?.name) {
    status = props.Status.select.name;
  } else if (props.status) {
    status = props.status;
  }

  // Extract Category
  let category = 'شغل';
  if (props['التصنيف']?.select?.name) {
    category = props['التصنيف'].select.name;
  } else if (props.Category?.select?.name) {
    category = props.Category.select.name;
  } else if (props.category) {
    category = props.category;
  }

  // Extract Priority
  let priority = 'عادية';
  if (props['الأهمية']?.select?.name) {
    priority = props['الأهمية'].select.name;
  } else if (props.Priority?.select?.name) {
    priority = props.Priority.select.name;
  } else if (props.priority) {
    priority = props.priority;
  }

  // Extract Duration
  let duration = 'أقل من ساعة';
  if (props['الوقت المتوقع']?.select?.name) {
    duration = props['الوقت المتوقع'].select.name;
  } else if (props.Duration?.select?.name) {
    duration = props.Duration.select.name;
  } else if (props.duration) {
    duration = props.duration;
  }

  // Extract Date
  let taskDate = '';
  if (props.date?.date?.start) {
    taskDate = props.date.date.start;
  } else if (props.Date?.date?.start) {
    taskDate = props.Date.date.start;
  } else if (props['التاريخ']?.date?.start) {
    taskDate = props['التاريخ'].date.start;
  } else if (rawItem.created_time) {
    taskDate = rawItem.created_time.split('T')[0];
  }

  parsedTasks.push({
    id: rawItem.id,
    ID_task: idTask,
    title: title || 'مهمة بدون عنوان',
    description: description || '',
    status: status,
    category: category,
    priority: priority,
    duration: duration,
    date: taskDate,
    'user ID': taskUserId || targetUserId,
    userId: taskUserId || targetUserId,
    userEmail: targetEmail
  });
}

// 3. Return clean, structured payload ready for Board rendering
return {
  json: {
    success: true,
    process: 'done',
    status: 'success',
    count: parsedTasks.length,
    userId: targetUserId,
    userEmail: targetEmail,
    data: parsedTasks,
    results: parsedTasks,
    tasks: parsedTasks
  }
};

// Invalid GET Action handler from Switch fallback
const query = $json.query || $json;
const receivedAction = query.Get || query.action || 'Unknown';

return {
  json: {
    isError: true,
    statusCode: 400,
    success: false,
    process: 'error',
    error: {
      message: `إجراء GET غير صالح أو غير معرّف: '${receivedAction}'`,
      code: 'INVALID_GET_ACTION',
      received: receivedAction
    }
  }
};
